import numpy as np
def equation(t, P, params):
    p=params
    s=np.sqrt(t); s1=np.sqrt(1+t); lP=np.log(P)
    return (p[0]+p[1]*P+p[2]*P**2 + s*(p[3]+p[4]*P+p[5]*P**2)
            + s1*(p[6]*P+p[7]*P*lP) + p[8]*s*P*lP + p[9]*P*np.sqrt(P))
